// Chung-Ang University Seoul (흑석) campus package. Data is generated by scripts/campuses/cau/build-package.mjs from the pilot
// (pilot/cau-seoul): 24 destructible models, and a baked ground (terrain, aprons, place pads, walls, stairs, planting) and
// the non-destructible context (OSM surroundings, 흑석로, 304관) that the engine reads instead of building its own.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, CAU_PLACEMENTS, CAU_BUILDING_BASE, CAU_HEIGHT_GRIDS, CAU_HEIGHT_RANGE_M, CAU_ENV_IDS, CAU_PROVENANCE } from './data.js';
import { CAU_FOOTPRINTS } from './footprints.js?v=tape41';

const MODEL_IDS = Object.freeze(CAU_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/cau/${file}`, import.meta.url).href;

export const HANYANG = Object.freeze({
  id: 'cau',
  meta: Object.freeze({ school: '중앙대학교', campus: '서울캠퍼스', short: '중앙대 서울', modelNoun: '중앙대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: CAU_PLACEMENTS,
  approvedCount: CAU_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['youngshin', 'library', 'pharmacy', 'centennial', 'lawSchool', 'seorabeol']),
  startBuildingId: 'youngshin',
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: CAU_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  // Finished display ground of the pilot (pads on the real outlines, forecourt and bowl levels already in it).
  terrain: Object.freeze({ heightGrids: CAU_HEIGHT_GRIDS, buildingBase: CAU_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30 DSM + floor-link evidence, pilot/cau-seoul); not a survey' }),
  environment: Object.freeze({ provenance: CAU_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); place pads, fill blocks, planting and heights estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: CAU_ENV_IDS, castShadow: Object.freeze([]), fade: Object.freeze({ centre_m: Object.freeze([-20, -20]), near_m: 340, far_m: 600, colour: '#cfdde3' }), playMargin_m: 30, source: 'pilot/cau-seoul preview ground, baked' }),
  }),
  // Hospitals in the baked context stay non-destructible; invisible hit proxies from their walls give them the shield
  // reaction (src/protected-buildings.js).
  protected: Object.freeze({ contextMaterials: Object.freeze(['ctx-wall-hospital']) }),
  // Hazard tape around every destructible building (src/engine/hazard-tape.js, user decision 2026-10-18).
  hazardTape: Object.freeze({ footprints: CAU_FOOTPRINTS }),
  scene: Object.freeze({
    background: '#cfdde3', fog: Object.freeze({ color: '#cfdde3', near: 700, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8a78', intensity: 1.3 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-100, 220, 120]), shadowSpan: 185 }),
    floor: Object.freeze({ color: '#b9b8b2', hidden: true, y: CAU_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default HANYANG;
